(site/'creator-profile.html').write_text(shell('creator-profile','전문가 콘텐츠 채널',hero('윤서진 변호사 채널<br><small style="font-size:.45em">가상 프로필 데모</small>','LAWYER CONTENT CREATOR','기업·계약 주제로 글과 영상을 제작하는 전문가 페이지 템플릿입니다.','pan-editorial-1.webp')+section('주요 글',blog_cards(),'작성일·출처와 함께 원문으로 이동하는 구조입니다.')+section('최근 영상',video_cards(),'YouTube 채널 링크 연동 예정.')+section('상담 연결','<a class="btn primary" href="consultation.html">비공개 상담 요청하기</a>','전화번호와 이메일은 화면 및 공개 소스에 노출하지 않습니다.')))
