(site/'advertising.html').write_text(shell('advertising','변호사 콘텐츠 광고',hero('광고는 표시하고,<br>전문성은 콘텐츠로 전달합니다.','PAN ADS · TRANSPARENT INVENTORY','후원 카드·쇼츠 슬롯·주제별 추천 영역을 제공하되 유료 노출 사실을 명확하게 안내합니다.','pan-editorial-6.webp')+section('상품 유형','<div class="pn-cards"><div class="pn-feature"><h3>주제별 후원 카드</h3><p>분야별 피드에서 상단 후원 영역에 표시하고 광고임을 알립니다.</p></div><div class="pn-feature"><h3>쇼츠 후원 콘텐츠</h3><p>유튜브 영상 중 사전 검수된 공개 영상만 연계합니다.</p></div><div class="pn-feature"><h3>지면·캠페인 통계</h3><p>노출과 클릭을 구분하고 유효 클릭을 집계합니다.</p></div></div>')+section('광고 신뢰 정책','<p class="pn-warning">광고가 변호사 자격·성과·전문성을 보증하지 않습니다. 추천 순위와 유료 노출은 분리됩니다. 변호사 광고 규정과 표시·광고 기준 검토 후 실제 판매를 개시합니다.</p>')+section('캠페인 미리보기','<a href="campaign-create.html" class="btn primary">광고 캠페인 만들기 →</a>')))
(site/'ad-ranking.html').write_text(shell('ad-ranking','콘텐츠 노출 알고리즘',hero('광고와 추천을 분리하는<br>공정한 발견 시스템.','RANKING TRANSPARENCY','추천 점수는 콘텐츠 주제 적합성, 최신성, 원문 신뢰도, 중복 여부 등을 참고합니다. 후원 콘텐츠는 별도 영역입니다.','pan-editorial-5.webp')+section('자연 추천 설계','<table class="pn-table"><thead><tr><th>요소</th><th>예시 가중치(제안)</th><th>원칙</th></tr></thead><tbody><tr><td>주제 연관성</td><td>40%</td><td>사용자 관심 분야 일치</td></tr><tr><td>출처 검증</td><td>25%</td><td>실명·원문 링크·작성자 확인</td></tr><tr><td>콘텐츠 품질</td><td>20%</td><td>유익성·중복 여부·최신성</td></tr><tr><td>콘텐츠 다양성</td><td>15%</td><td>같은 계정 과다 노출 방지</td></tr></tbody></table><p class="muted small">위 수치는 실제 운영 데이터가 아닌 알고리즘 설계 예시입니다.</p>')+section('유료 광고 지면',featured,'광고는 추천 점수와 혼합하지 않습니다.')+section('이용자 보호','<p>사실과 다른 광고, 보장형 표현, 무단 사칭, 개인정보를 포함한 영상은 게재하지 않습니다.</p>')))
(site/'ai-search.html').write_text(shell('ai-search','AI 검색 시대의 변호사 브랜드',hero('노출을 약속하지 않고,<br>검색 자산을 설계합니다.','AI DISCOVERABILITY','공개 블로그와 영상, 검색 가능한 전문 프로필을 함께 구축하는 전략입니다.','pan-editorial-4.webp')+section('왜 공개 콘텐츠가 중요한가','<div class="pn-cards"><div class="pn-feature"><h3>독립적인 URL</h3><p>콘텐츠를 직접 통제하는 공개 주소가 쌓입니다.</p></div><div class="pn-feature"><h3>작성자 신뢰</h3><p>실제 변호사·사무소·원문 출처를 명시합니다.</p></div><div class="pn-feature"><h3>검색엔진 친화성</h3><p>텍스트와 메타데이터, 내부 링크, 구조화 데이터를 점검합니다.</p></div></div>')+section('공식 가이드에 근거한 설명','<p class="pn-warning">Google은 AI Overviews와 AI Mode가 기존 검색의 색인 자격을 참고한다고 설명하지만, 특정 글의 수집·노출·인용은 보장하지 않습니다. 네이버 블로그 전체가 AI 검색에서 무가치하거나 검색에서 항상 제외된다는 단정은 하지 않습니다.</p><p><a href="https://developers.google.com/search/docs/appearance/ai-features">Google 공식 AI 검색 가이드</a> · <a href="https://help.naver.com/service/5626/contents/8022?osType=COMMONOS">네이버 검색 순위 안내</a></p>')))
(site/'blogger-connect.html').write_text(shell('blogger-connect','Google Blogger 연결',hero('나의 구글블로그를<br>전문가 콘텐츠 채널로.','BLOGGER CONNECT','본인 소유의 공개 Blogger URL을 등록하고 관리자 검토 후 로판에 노출합니다.','pan-editorial-4.webp')+section('블로그 연결 신청','<form class="pn-form" data-pan-api="/api/content" data-content-type="blog"><label>등록 이메일(본인 계정) *</label><input class="pn-field" name="email" type="email" required><label>글 제목 *</label><input class="pn-field" name="title" required maxlength="120"><label>Google Blogger 게시글 URL *</label><input class="pn-field" name="url" required type="url" placeholder="https://example.blogspot.com/..."><label>콘텐츠 요약</label><textarea class="pn-field" name="summary" maxlength="1000"></textarea><label><input type="checkbox" name="rights" required> 직접 작성하거나 게시할 권한을 가진 콘텐츠입니다.</label><button type="submit">게시글 등록 요청</button><p class="pn-api-result" role="status"></p></form>','URL 소유권과 저작권 검증 후 게시합니다.')+section('운영 절차','<p>계정 인증 → URL·콘텐츠 권리 확인 → 관리자 검수 → 글 제목·요약·원문 링크 노출 → 업데이트 주기 설정.</p>')))
(site/'youtube-connect.html').write_text(shell('youtube-connect','유튜브 채널·쇼츠 등록',hero('내 영상이 잠재 고객과<br>만나는 또 하나의 지면.','YOUTUBE SHORTS CONNECT','내 유튜브 영상의 공개 URL을 등록하면 로판의 쇼츠·영상 영역에 반영할 수 있습니다.','pan-editorial-2.webp')+section('유튜브 영상 등록','<form class="pn-form" data-pan-api="/api/content" data-content-type="video"><label>등록 이메일 *</label><input class="pn-field" name="email" required type="email"><label>영상 제목 *</label><input class="pn-field" name="title" required maxlength="120"><label>YouTube 공개 영상 URL *</label><input class="pn-field" name="url" required type="url" placeholder="https://www.youtube.com/shorts/..."><label>콘텐츠 요약</label><textarea class="pn-field" name="summary" maxlength="1000"></textarea><label><input type="checkbox" name="rights" required> 본인이 게시했거나 정당한 사용 권리를 보유하고 있습니다.</label><button type="submit">영상 등록 요청</button><p class="pn-api-result" role="status"></p></form>','유튜브 API 키 없이도 URL을 제출할 수 있습니다. 실제 메타데이터 자동 갱신에는 API 설정이 필요합니다.')+section('쇼츠 지면 미리보기',video_cards())))
(site/'campaign-create.html').write_text(shell('campaign-create','후원 콘텐츠 캠페인 신청',hero('후원 캠페인도<br>투명하게 시작하세요.','CAMPAIGN STUDIO','변호사 광고 규정 검수 전에는 실제 비용을 청구하지 않습니다.','pan-editorial-6.webp')+section('광고 신청 초안','<form class="pn-form" data-pan-api="/api/campaign"><label>연락 받을 이메일 *</label><input name="email" class="pn-field" type="email" required><label>광고할 콘텐츠 URL *</label><input name="url" class="pn-field" type="url" required><label>광고 영역</label><select name="placement" class="pn-field"><option value="sponsored">후원 카드</option><option value="shorts">쇼츠 추천</option><option value="topic">주제별 후원 영역</option></select><label>예산 제안(원)</label><input name="budget" class="pn-field" type="number" min="0" placeholder="예: 50000"><label><input name="rights" type="checkbox" required> 콘텐츠 권리·광고심사 정책을 준수하겠습니다.</label><button type="submit">캠페인 검토 요청</button><p class="pn-api-result" role="status"></p></form>','유료 상품 개시는 별도 계약과 승인 이후 진행됩니다.')+section('투명한 광고 집계','<div class="pn-grid-metrics"><div><strong>노출</strong><p>실제 지면 표시 횟수</p></div><div><strong>클릭</strong><p>사람의 유효 링크 클릭</p></div><div><strong>전환</strong><p>동의된 상담 의향 이벤트</p></div><div><strong>심사</strong><p>운영정책 위반 검토</p></div></div>')))
(site/'analytics-guide.html').write_text(shell('analytics-guide','마케팅 대시보드 안내',hero('나의 콘텐츠가<br>어떻게 소비되는지 확인하세요.','ANALYTICS FOR LAWYERS','노출·클릭·콘텐츠 저장·상담 요청을 각각 구분해 제공합니다.','pan-editorial-1.webp')+section('분석 지표 정의','<table class="pn-table"><tr><th>지표</th><th>계산 기준</th><th>주의 사항</th></tr><tr><td>콘텐츠 노출</td><td>실제 가시영역 표시 이벤트</td><td>조회수와 다름</td></tr><tr><td>링크 클릭</td><td>유효 사용자 클릭</td><td>봇·중복 필터 적용</td></tr><tr><td>상담 신청</td><td>접수 성공 이벤트</td><td>실제 수임과 다름</td></tr><tr><td>광고 지표</td><td>후원 지면별 노출·클릭</td><td>일반 추천과 분리</td></tr></table>')+section('내 활동 확인','<a href="creator-studio.html" class="btn primary">콘텐츠 관리 시작</a>','운영환경의 실제 데이터 연결 전에는 샘플 통계만 표시합니다.')))
(site/'creator-studio.html').write_text(shell('creator-studio','변호사 크리에이터 스튜디오',hero('전문성을 발행하고,<br>나만의 지면을 관리하세요.','CREATOR STUDIO','블로그와 쇼츠, 공개 프로필, 광고 성과를 한 곳에서 관리하는 전문가용 메뉴입니다.','pan-editorial-1.webp')+section('콘텐츠 관리자','<div class="pn-cards"><a class="pn-feature" href="blogger-connect.html"><h3>구글블로그 등록</h3><p>원문 소유권을 확인해 공개 글을 등록합니다.</p></a><a class="pn-feature" href="youtube-connect.html"><h3>YouTube·쇼츠 등록</h3><p>영상 링크와 채널을 연결합니다.</p></a><a class="pn-feature" href="creator-profile.html"><h3>프로필 미리보기</h3><p>공개할 이름·상호·지역·전문 분야를 확인합니다.</p></a></div>')+section('광고·노출','<div class="pn-more"><a href="campaign-create.html">캠페인 신청 →</a><a href="ad-ranking.html">노출 규정 →</a><a href="analytics-guide.html">성과분석 지침 →</a></div>')+section('개인정보 설정','<p class="pn-warning">전화번호와 이메일은 관리자 정보로 보관하며, 방문자에게는 전화 연결 요청·메일 문의 버튼만 노출합니다. 전화 중계번호 발급 전에는 실전화 연결을 제공하지 않습니다.</p>')))
(site/'free-signup.html').write_text(shell('free-signup','로판 무료 회원가입',hero('좋은 위치는 먼저 준비한<br>전문가의 콘텐츠에서 시작됩니다.','FREE MEMBER REGISTRATION','무료 계정을 만들고 공개 프로필·구글블로그·유튜브 콘텐츠 등록 신청을 시작하세요.','pan-editorial-1.webp')+section('무료회원 가입 신청','<form class="pn-form" data-pan-api="/api/signup"><label>이메일 *</label><input name="email" type="email" required class="pn-field"><label>성함 *</label><input name="name" required maxlength="60" class="pn-field"><label>소속 법무법인·법률사무소</label><input name="firm" maxlength="100" class="pn-field"><label>지역</label><input name="region" maxlength="60" class="pn-field" placeholder="예: 서울 서초구"><label>주요 전문 분야</label><input name="practice" maxlength="120" class="pn-field" placeholder="예: 민사·기업 자문"><label>구글블로그 URL</label><input name="blog_url" type="url" class="pn-field" placeholder="https://example.blogspot.com"><label>유튜브 채널 URL</label><input name="youtube_url" type="url" class="pn-field" placeholder="https://www.youtube.com/@..."><fieldset><label><input name="terms" type="checkbox" required> [필수] 이용약관 및 개인정보처리방침을 확인했습니다.</label><label><input name="marketing" type="checkbox"> [선택] 마케팅 광고성 이메일 수신에 명시적으로 동의합니다.</label></fieldset><button type="submit">무료 계정 등록·이메일 인증</button><p role="status" class="pn-api-result"></p><small>가입 요청 후 이메일 인증을 완료해야 활성화됩니다. 공개 변호사 프로필 노출은 별도의 자격 검증 이후 진행됩니다.</small></form>','메일 발송 및 저장 기능은 제공된 API 서버 설정이 완료돼야 사용할 수 있습니다.')+section('무료 가입 후 할 수 있는 일','<div class="pn-cards"><div class="pn-feature"><h3>무료 공개 프로필</h3><p>이름·상호·주소·전문 분야를 공개하고 고객에게 소개합니다.</p></div><div class="pn-feature"><h3>내 콘텐츠 등록</h3><p>구글블로그와 유튜브의 본인 소유 URL을 등록합니다.</p></div><div class="pn-feature"><h3>상담 문의 연결</h3><p>전화·이메일을 숨기고 버튼으로 연결 요청을 받습니다.</p></div></div>')))
(site/'phone-privacy.html').write_text(shell('phone-privacy','안심전화·이메일 비공개 정책',hero('변호사의 연락처는 보호하고,<br>상담의 문은 열어둡니다.','PRIVACY FIRST CONTACT','공개할 정보와 숨겨야 할 정보를 명확히 구분합니다.','pan-editorial-5.webp')+section('정보 공개 기준','<table class="pn-table"><tr><th>공개 정보</th><th>비공개 정보</th></tr><tr><td>이름, 법무법인·법률사무소, 영업 주소, 전문 분야, 공개 콘텐츠</td><td>직통 전화, 개인 이메일, 관리계정 이메일, 비공개 상담내역</td></tr></table>')+section('전화·메일 버튼 동작','<div class="pn-cards"><div class="pn-feature"><h3>전화 연결 요청</h3><p>안심전화 서비스 연동 전에는 연결 요청만 접수합니다.</p></div><div class="pn-feature"><h3>메일 문의</h3><p>계정에서 인증한 이메일로 서버가 안내하며 공개 페이지에 주소를 노출하지 않습니다.</p></div><div class="pn-feature"><h3>고객 동의</h3><p>문의 목적을 알리고 필요한 항목에 한해 개인정보를 수집합니다.</p></div></div>')))
